from pathlib import Path
import re

ROOT = Path('.')


def read(path):
    return (ROOT / path).read_text(encoding='utf-8')


def write(path, text):
    (ROOT / path).write_text(text, encoding='utf-8')


def replace_once(path, old, new):
    text = read(path)
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{path}: expected one exact match, got {count}')
    write(path, text.replace(old, new, 1))


def insert_before(path, anchor, addition):
    text = read(path)
    count = text.count(anchor)
    if count != 1:
        raise SystemExit(f'{path}: expected one anchor, got {count}: {anchor[:80]}')
    write(path, text.replace(anchor, addition + anchor, 1))


